(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["id"] = {"ui":{"skip":"Langsung ke isi","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tidak ada bahasa yang cocok","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Ganti antara tema terang dan gelap","theme.toLight":"Ganti ke tema terang","theme.toDark":"Ganti ke tema gelap","words.underline":"Garis bawahi kata-kata ini di halaman","words.underlineHelp":"Arahkan kursor atau ketuk kata bergaris titik-titik untuk melihat artinya.","index.title":"AI-gile: tim dev AI-mu, dalam satu papan","index.description":"AI-gile adalah papan kanban untuk tim pemrograman AI. Mereka bekerja saat kamu tidur; kamu cukup mengurus satu tumpukan pendek: hal yang perlu diputuskan, dites, dan disetujui.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Tim dev AI-mu, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum selesai: terima kasih sudah mau mencoba!","hero.lede":"Mereka membangun selagi kamu tidur. Kamu bangun dan menemukan satu tumpukan pendek: beberapa pertanyaan, beberapa hal untuk dites, satu atau dua berlian ungu. Klik, setujui, lanjut ngopi.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan di browser","dl.soon":"Segera hadir","dl.notify":"🔔 Kabari aku saat dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tapi timnya tidak butuh kopi stand-up. (Stand-up tetap jalan, sih.)","pitch.h2":"AI-gile dalam sebanyak kata yang kamu mau","pitch.lede":"Pilih panjangnya, dari satu kata sampai 144. Setiap panjang punya deskripsinya sendiri, ditulis khusus untuk ukuran itu. Geser slider atau pakai tombol panah.","pitch.rangeLabel":"Panjang dalam kata","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} kata","pitch.words.other":"{n} kata","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kartu di papan sekarang","count.line.html.other":"{n} kartu di papan sekarang","features.aria":"Apa yang dilakukannya","f.pile.h":"Satu tumpukan untukmu","f.pile.html":"<b>Untukmu</b> berisi semua yang menunggumu, dari semua proyek: pertanyaan, hal untuk dites, tugas yang hanya bisa dikerjakan manusia. Antreanmu memberi tahu apa yang berikutnya dan berapa lama.","f.sleep.h":"Tim yang bekerja saat kamu tidur","f.sleep.p":"Setiap proyek punya lead dan tim agen AI. Beri komentar di sebuah kartu, tim pun bangun, mengerjakannya, lalu mengembalikannya dengan langkah-langkah yang bisa diikuti manusia yang sedang capek.","f.tester.h":"Penguji AI memeriksa lebih dulu","f.tester.p":"Sebelum sampai ke kamu, penguji mengikuti langkah-langkahnya di salinan aplikasi dan menunjukkan apa yang dilihatnya, lengkap dengan tangkapan layar. Telusuri yang lolos dan setujui dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap serah terima menunjukkan apa yang berubah: berkas, diff, tangkapan layar. Tidak perlu membuka satu per satu aplikasi untuk tahu sudah selesai atau belum.","f.chat.h":"Ngobrol dengan lead-mu","f.chat.p":"Bilah ala Discord: satu ikon per proyek, berlian ungu untuk yang butuh kamu. Kirim ide ke lead; ia mengubahnya jadi kartu dan rencana, dengan tombol ✅ Go.","f.tidy.h":"Rapi dengan sendirinya","f.tidy.p":"Kartu yang berkaitan digabung jadi satu, judul yang berantakan dibereskan, dan pemeriksaan token menjaga kode tetap ramping. Lebih sedikit yang harus dipindah-pindah, lebih sedikit yang harus dipikirkan.","f.private.h":"Milikmu, di komputermu","f.private.li1":"Papan berjalan di mesinmu sendiri dan hanya menjawab kamu.","f.private.li2":"Pesan pribadi antarmanusia dienkripsi ujung ke ujung.","f.private.li3":"Tanpa akun, tanpa pelacak, tanpa cookie.","f.lang.h":"Dalam bahasamu","f.lang.p":"Lebih dari 120 bahasa, dari Belanda, Wales, dan Jepang sampai bajak laut, Yoda, dan Klingon, dengan tombol cepat kembali ke bahasa Inggris untuk istilah pengembang.","tl.aria":"Lini masa dari percakapan pertama sampai peta jalan","tl.h2":"Dari obrolan pertama sampai yang berikutnya","tl.lede":"Tanggal dan jam sungguhan, dalam zona waktumu sendiri. Setelah hari ini, itu baru rencana, tanpa janji tanggal.","tl.today":"Hari ini","tl.planned":"direncanakan","tl.cards.one":"{n} kartu","tl.cards.other":"{n} kartu","join.h2":"Ikut serta","join.lede":"AI-gile dibuat oleh satu manusia kecil dan banyak agen yang sabar. Untuk sekarang masih privat, alfa tertutup bersama teman-teman. Mau ikut coba saat dibuka?","join.btn":"Daftarkan minat","join.small":"Kami kirim email, tidak lebih","footer.tag":"AI-gile. Tanpa pelacak, tanpa cookie, tanpa kopi stand-up.","footer.licence":"Lisensi bisnis","footer.status":"Status","footer.privacy":"Apa yang kami simpan","form.sending":"Mengirim…","form.failed":"Belum berhasil: coba lagi nanti.","form.offline":"AI-gile tidak terjangkau: coba lagi nanti.","form.keep":"Kami hanya memakai ini untuk membalasmu, lalu menghapusnya. Tanpa pelacak, tanpa cookie.","form.keepLink":"Apa yang kami simpan","interest.title":"AI-gile: kabari aku saat alfa dibuka","interest.description":"Tinggalkan emailmu untuk tahu kapan alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Kabari aku saat dibuka","interest.lede":"AI-gile masih dalam pra-alfa tertutup. Tinggalkan emailmu dan kami akan menulis sekali, saat ada tempat untukmu.","interest.email":"Emailmu","interest.which":"Tes yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, nanti","interest.both":"Salah satu, mana yang duluan","interest.submit":"Masukkan aku ke daftar","interest.thanks":"Terima kasih! Kamu sudah ada di daftar.","licence.title":"AI-gile: lisensi bisnis","licence.description":"Memakai AI-gile untuk bisnismu? Ajukan lisensi bisnis gratis.","licence.h1":"📜 Lisensi bisnis","licence.lede":"Memakai AI-gile di tempat kerja? Ceritakan siapa kamu dan apa yang kamu kerjakan. Kalau bermanfaat, lisensinya gratis.","licence.company":"Perusahaan","licence.website":"Situs web","licence.what":"Bidang usahamu","licence.how":"Bagaimana ini membantu dunia","licence.email":"Email","licence.submit":"Ajukan","licence.thanks":"Terima kasih! Kami akan membalas lewat email.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semua tenang","status.intro":"Apakah AI-gile sedang berjalan? Halaman ini memeriksa situs web, berbagi papan, panggilan, dan unduhan setiap 5 menit.","status.up":"Berjalan (menjawab dalam {ms} ms)","status.slow":"Tidak menjawab pemeriksaan terakhir, mencoba lagi","status.down":"Mati: tidak menjawab dua pemeriksaan terakhir","status.svc.web":"Situs web","status.svc.web.offers":"Situs ini: apa itu AI-gile, dan formulir minat","status.svc.boards":"Berbagi papan","status.svc.boards.offers":"Papan publik, pesan antarteman, dan undangan","status.svc.calls":"Panggilan","status.svc.calls.offers":"Suara, video, dan berbagi layar di AI-gile","status.svc.download":"Unduhan","status.svc.download.offers":"Penginstal Windows dan tautan undangan","status.checking":"Memeriksa…","status.offline":"Layanan status belum terjangkau (mencoba lagi)","status.updated":"diperbarui {ago}","status.justNow":"baru saja","status.min":"{n} menit lalu","status.hours":"{n} jam lalu","status.days":"{n} hari lalu","privacy.title":"AI-gile: apa yang kami simpan","privacy.h1":"Apa yang kami simpan","privacy.lede":"Singkatnya: hanya yang kamu kirim ke kami, dan tidak lama.","privacy.only":"Hanya yang kamu kirim ke kami: yang kamu ketik di formulir, seperti emailmu. Tidak ada hal lain tentang dirimu.","privacy.sealed":"Datanya disegel sehingga server kami tidak bisa membacanya: di browsermu sebelum dikirim (di browser lama, begitu tiba). Hanya papan kami sendiri yang bisa membukanya.","privacy.server":"Data dihapus dari server begitu sampai di papan kami. Apa pun yang masih ada di sana setelah 30 hari tetap dihapus.","privacy.board":"Kami menyimpannya di papan kami hanya sampai kami membalasmu, lalu menghapusnya juga dari sana.","privacy.none":"Tanpa pelacak, tanpa cookie, tanpa analitik.","privacy.local":"Bahasa dan pilihan mode terang atau gelapmu tetap di browsermu sendiri. Tidak pernah dikirim ke kami.","privacy.ask":"Ingin dihapus lebih cepat? Balas email kami dan bilang saja.","live.h2":"Lihat proses pembuatannya, langsung","live.caption":"Setiap kartu disembunyikan: Anda melihat bentuk pekerjaannya, bukan kata-katanya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.last.now":"Kartu terakhir dipindahkan baru saja","live.last.min.one":"Kartu terakhir dipindahkan {n} menit lalu","live.last.min.other":"Kartu terakhir dipindahkan {n} menit lalu","live.last.hour.one":"Kartu terakhir dipindahkan {n} jam lalu","live.last.hour.other":"Kartu terakhir dipindahkan {n} jam lalu","live.last.day.one":"Kartu terakhir dipindahkan {n} hari lalu","live.last.day.other":"Kartu terakhir dipindahkan {n} hari lalu","live.offline":"Papan langsung sedang istirahat sebentar. Cek lagi nanti ya.","live.cols":"Backlog|Akan dikerjakan|Dikerjakan|Tim memeriksa|Giliranmu tes|Untuk tim|Selesai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Didelegasikan."]},{"n":2,"texts":["Kanban robot.","Agen, tertata.","Ide, jadi."]},{"n":3,"texts":["Kanban untuk robot.","Ide jadi fitur.","Kanban agen gratis."]},{"n":5,"texts":["Papan kanban yang dijalankan agen.","Kamu menulis kartu. Agen membangun.","Gratis, lokal, teruji, agak konyol."]},{"n":8,"texts":["Papan kanban gratis tempat agen AI bekerja.","Tulis ide. Agen membangunnya. Kamu menyetujui.","Agile untuk satu manusia dan banyak robot sabar."]},{"n":13,"texts":["Papan kanban di komputermu, tempat agen AI mengambil kartu, mengerjakannya, lalu mengembalikannya padamu.","Tulis sebuah ide. Tim agen membangunnya, lalu seorang penguji memeriksanya sebelum sampai ke kamu.","Gratis, tanpa akun, tanpa pelacak: satu papan, beberapa robot, dan kamu yang memegang kendali."]},{"n":21,"texts":["AI-gile adalah papan kanban untuk bekerja bersama agen pemrograman AI. Mereka mengambil kartunya; kamu yang mengetes dan menyetujuinya.","Setiap proyek punya seorang lead dan tim agen AI. Beri komentar di kartu mana pun, dan tim langsung bekerja.","Papan tugas pribadi yang gratis dan berjalan di komputermu sendiri. Pekerjanya robot. Yang berkata ya adalah kamu."]},{"n":34,"texts":["Kamu menaruh ide di sebuah papan. Tim agen AI mengubahnya jadi fitur yang berfungsi, mengetesnya, lalu menyerahkannya kembali dengan langkah-langkah untuk dicoba. Tidak ada yang dianggap selesai sebelum kamu bilang begitu.","AI-gile adalah papan kanban buatan sendiri yang dibuat Rich dengan banyak bantuan dari agen-agen yang kini diurusnya. Gratis, berjalan di komputermu, dan dibagikan ke teman-teman, bukan dijual.","Bayangkan papan kanban biasa, dengan kolom dari Backlog sampai Selesai, hanya saja kartunya diambil oleh agen AI. Mereka melaporkan kemajuan, bertanya saat buntu, dan selalu menunggu acungan jempolmu."]},{"n":55,"texts":["AI-gile adalah papan kanban yang timnya terdiri dari agen AI. Setiap proyek punya lead yang merencanakan pekerjaan dan pembantu yang membangunnya. Saat sebuah fitur siap, penguji AI mencobanya dan mengambil tangkapan layar, lalu fitur itu mendarat di tumpukanmu. Setujui, atau beri komentar dan mereka mengerjakannya ulang.","Awalnya ini cara satu orang melacak banyak sesi pemrograman AI sekaligus, lalu tumbuh jadi papan sungguhan. Ia berjalan di mesinmu, tanpa akun, tanpa pelacak. Gratis untuk teman dan siapa pun yang penasaran. Ia juga belum selesai, jadi harap maklum kalau ada sisi kasar dan kejutan kecil.","Ini versi jujurnya. Kamu tetap harus punya ide, dan tetap harus memeriksa hasilnya. Yang dikerjakan AI-gile adalah semua yang ada di antaranya: menjaga kartu tetap urut, membangunkan agen yang tepat saat kamu berkomentar, menunjukkan persis apa yang berubah, dan menyimpan semuanya dalam satu tumpukan pendek untukmu."]},{"n":89,"texts":["AI-gile adalah papan kanban gratis yang kamu jalankan di komputermu sendiri. Alih-alih orang, setiap proyek punya tim agen AI: seorang lead yang mengubah ide-idemu jadi kartu dan rencana, dan pembantu yang mengambil kartu sesuai urutan prioritas. Setelah sesuatu selesai dibangun, penguji AI mengikuti langkah tesnya dan menunjukkan apa yang dilihatnya. Lalu hasilnya menunggu di satu tumpukan bernama Untukmu. Kamu menyetujuinya, atau memberi komentar dan tim mencoba sekali lagi. Tidak ada yang sampai ke Selesai tanpa kamu.","Beberapa fitur yang mungkin tak kamu duga. Penjaga malam mengisi kolom Akan dikerjakan selagi kamu tidur, dengan memilih kartu yang tidak butuh jawabanmu. Penghitung token menunjukkan berapa banyak yang dipakai agen hari ini dan minggu ini, dan Mode Tanpa Token menyuruh mereka berhenti menghabiskan. Kamu bisa berkirim pesan dengan teman, dan pesan pribadi dienkripsi ujung ke ujung. Papan ini berbahasa sekitar 120 bahasa, termasuk Belanda, Flemish, bajak laut, dan Klingon. Semuanya tanpa biaya sepeser pun, dan tak ada yang berusaha menjualnya padamu.","AI-gile adalah proyek kecil pribadi, bukan perusahaan. Rich ingin mengurus beberapa proyek pemrograman AI tanpa membuka tiap aplikasi untuk mengeceknya, jadi ia dan para agen membuat papan untuk itu, lalu memakai papan itu untuk membangun sisanya. Statusnya pra-alfa tertutup, artinya ia berfungsi, kurang lebih, untuk segelintir teman. Tidak ada halaman harga, tidak ada newsletter, dan tidak ada rencana pertumbuhan. Kalau kedengarannya berguna, kamu bisa minta mencobanya saat dibuka sedikit lebih lebar."]},{"n":144,"texts":["AI-gile adalah papan kanban untuk satu manusia dan banyak agen AI. Ia berjalan di komputermu sendiri dan sepenuhnya gratis. Kamu menambahkan proyek, dan setiap proyek mendapat lead beserta tim kecil. Kamu ngobrol dengan lead, agak mirip Discord, dan menjelaskan sebuah ide; lead mengubahnya jadi kartu dan rencana, lalu menunggu kamu menekan Go. Tim mengerjakan kartu sesuai urutan prioritas, memakai antarmuka baris perintah sederhana yang dibuat untuk model bahasa. Sebelum apa pun kembali kepadamu, penguji AI mengikuti langkah-langkahnya di salinan aplikasi dan melampirkan tangkapan layar. Pekerjaan yang selesai mendarat di tumpukanmu bersama berkas yang berubah dan diff-nya. Kamu menyetujuinya, atau meninggalkan komentar, lalu tim bangun dan mencoba lagi. Hanya kamu yang bisa memindahkan kartu ke Selesai.","Kira-kira begini sehari bersama AI-gile. Malam hari kamu meninggalkan beberapa komentar: tombol ini salah tempat, daftar itu harus diurutkan, bisakah ada mode gelap. Kamu pergi tidur. Para agen membaca komentarnya, membuat perubahan, mengetesnya, dan menyerahkannya kembali padamu. Kalau kolom Akan dikerjakan kosong, penjaga malam mengisinya dari backlog dengan kartu yang tidak butuh jawabanmu. Pagi harinya ada satu tumpukan pendek: beberapa pertanyaan dan beberapa hal untuk dicoba, masing-masing dengan langkah yang bisa diikuti orang mengantuk dan tangkapan layar yang membuktikannya berfungsi. Kamu menelusurinya, menyetujui yang bagus dan mengembalikan sisanya. Penghitung token menunjukkan pemakaiannya, dan Mode Tanpa Token siap untuk minggu-minggu hemat. Kalau ada yang kurang pas, tinggal komentar lagi dan siklusnya berulang. Lalu kamu sarapan, hal yang belum bisa dibantu para agen.","Pertama, apa yang bukan AI-gile. Ia bukan startup, tidak dijual, dan tak seorang pun mengumpulkan datamu. Ia papan gratis yang berjalan di komputermu, tanpa akun, tanpa pelacak, dan tanpa cookie. Yang ia adalah: satu tempat rapi untuk melihat semua proyek pemrograman AI sekaligus, dengan tim agen yang mengerjakan kartu dan kamu yang mengambil keputusan. Ia menggabungkan kartu yang berkaitan, membereskan judul yang berantakan, dan menjaga agar kodenya tetap ramping. Ia berbicara sekitar 120 bahasa, dari Belanda dan Flemish sampai bajak laut dan Klingon. Teman-teman bisa saling berkirim pesan, secara pribadi dan terenkripsi. Ia dibuat oleh Rich dan banyak agen yang sabar, kebanyakan dengan memakai dirinya sendiri. Statusnya pra-alfa tertutup, jadi di beberapa bagian masih kasar. Kalau kedengarannya seru, mintalah baik-baik dan kamu mungkin bisa masuk lebih awal."]}],"quips":{"1":"Satu kata. Berani. Mungkin terlalu berani.","3":"Tiga kata. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Delapan kata. Masih lebih pendek daripada satu stand-up.","21":"Panjangnya itu story point, omong-omong. Ya iyalah.","55":"Lima puluh lima kata. Dua kartu selesai selagi kamu membaca ini.","144":"Itu yang terpanjang. Tidak ada 233. Para agen sudah tidur."}},"timeline":{"first-idea.name":"Ide pertama","first-idea.line":"Percakapan pertama, sebelum ada satu baris kode pun.","first-board.name":"Papan pertama","first-board.line":"Papan yang melacak pembuatannya sendiri: kartu, kolom, seret dan lepas, proyek.","team-roles.name":"Tim dan peran","team-roles.line":"Profil agen, templat tim, ruang, dan siapa mengerjakan apa.","install.name":"Pemasangan dan rilis","install.line":"Satu zip yang bisa dipasang teman, pembaruan otomatis, kanal, dan kembali ke versi lama.","usage-saver.name":"Penghemat pemakaian","usage-saver.line":"Ukur biaya tiap proses, jaga kode tetap ramping, hemat batasmu.","friends.name":"Teman dan berbagi","friends.line":"Pesan pribadi, relai teracak, undangan, peran, dan proyek bersama.","languages.name":"Bahasa","languages.line":"Setiap teks layar dalam berkas bahasa, dimulai dari Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Penguji memeriksa setiap serah terima lebih dulu dan menunjukkan apa yang dilihatnya.","website.name":"Situs web","website.line":"aigile.lol, teaser, dan lini masa ini.","streaming.name":"Obrolan dan streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF, dan emoji.","no-ai.name":"Edisi Tanpa AI","no-ai.line":"Papan untuk orang yang menulis kode tanpa AI, dan papan publik.","night-watch.name":"Penjaga malam","night-watch.line":"Seorang penjaga dan Scrum Master menjaga tim tetap fokus selagi kamu tidur.","p-more.name":"Yang lainnya","p-more.line":"Ide-ide kecil yang masih menunggu giliran.","p-android.name":"Ponsel dan Android","p-android.line":"Buka papanmu dari ponsel, lalu aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, situs langsung, lalu beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"Lebih dari seratus bahasa, dan mode imersi untuk pembelajar.","p-engines.name":"Lebih banyak mesin AI","p-engines.line":"Pilih Claude, Codex, atau Gemini untuk tiap agen.","p-pro.name":"Praktik profesional","p-pro.line":"Label risiko, gerbang merge, kartu insiden, dan pagar pengaman.","p-self.name":"Menjagamu","p-self.line":"Mode lelah, pengingat merawat diri, dan 4:20.","p-servers.name":"Server dan skala","p-servers.line":"Pengaturan server global, peran, dan perencanaan untuk berkembang.","p-livestream.name":"Tambahan streaming","p-livestream.line":"Obrolan Twitch, emoji kustom, dan tampilan langsung publik."},"words":{"button":"📖 Istilah developer","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Cari kata…","none":"Tidak ada kata yang cocok.","close":"Tutup","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folder kode proyek beserta seluruh riwayat commit-nya, biasanya juga disimpan di GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Jalur kerja terpisah di dalam kode, supaya perubahan bisa dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"commit","g":"build","word":"Commit","text":"Cuplikan kode yang tersimpan, dengan catatan singkat tentang apa yang berubah. Kamu selalu bisa kembali ke salah satunya.","also":["commit"]},{"id":"push","g":"build","word":"Push","text":"Mengirim cuplikan tersimpan (commit) dari komputer ini ke GitHub, supaya punya cadangan dan bisa dibagikan."},{"id":"merge","g":"build","word":"Merge","text":"Menggabungkan perubahan sebuah branch kembali ke versi utama."},{"id":"pr","g":"build","word":"Pull request","text":"Meminta perubahan sebuah branch diperiksa dan digabungkan ke versi utama.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Merapikan kode tanpa mengubah fungsinya: file lebih kecil, nama lebih jelas, lebih sedikit pengulangan."},{"id":"bug","g":"build","word":"Bug","text":"Sesuatu yang tidak berfungsi sebagaimana mestinya.","also":["bug"]},{"id":"test","g":"build","word":"Tes","text":"Mencoba pekerjaan yang sudah jadi untuk memastikan hasilnya sesuai permintaan, sebelum kamu menerimanya.","also":["tes","test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Merilis versi baru agar bisa dipakai, misalnya ke server tempat orang memakainya."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ide dan pekerjaan yang belum direncanakan. Tidak ada yang dikerjakan di sana sampai dipindah ke Akan dikerjakan."},{"id":"sprint","g":"team","word":"Sprint","text":"Rentang kerja singkat (biasanya satu atau dua minggu) dengan sekumpulan kartu yang disepakati untuk diselesaikan.","also":["sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Check-in singkat: apa yang dikerjakan tiap anggota tim, apa yang akan dikerjakan berikutnya, dan apa yang menghambat.","also":["standup","stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board berkolom (Akan dikerjakan, Dikerjakan, Selesai) tempat kartu bergerak dari kiri ke kanan seiring pekerjaan berjalan."},{"id":"wip","g":"team","word":"Batas WIP","text":"Work in progress: jumlah kartu maksimal yang sebaiknya ada di satu kolom, supaya tim menyelesaikan sesuatu sebelum memulai yang lain.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agen","text":"AI yang bekerja sendiri pada suatu tugas: membaca kode, membuat perubahan, menjalankan pengecekan, lalu melapor balik.","also":["agen","agent"]},{"id":"token","g":"team","word":"Token","text":"Satuan penghitungan pemakaian AI: kira-kira beberapa huruf teks yang dibaca atau ditulis. Makin sedikit token, makin banyak sisa paketmu.","also":["token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Perintah kecil yang berjalan sendiri pada saat tertentu, mis. ketika sesi AI dimulai, supaya tim mendengar komentarmu.","also":["hook","hooks"]}]}};
